pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 newMin) internal {
        try c.SetMinSum(1) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(newMin) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == true);
    }

    function testFuzz_run(uint256 newMin) public {
        _run(newMin);
    }

    receive() external payable { }
}
